import os
import base64
import tarfile
import io
import subprocess

print("=== Aggiornamento Sorgente Song (maestro-studio) ===")
app_dir = "/var/www/maestro-studio"
os.makedirs(app_dir, exist_ok=True)
os.chdir(app_dir)

b64_str = """"""

print("Estrazione file sorgente...")
tar_bytes = base64.b64decode(b64_str)
with tarfile.open(fileobj=io.BytesIO(tar_bytes), mode="r:gz") as tar:
    tar.extractall(path=".")

print("Installazione dipendenze...")
subprocess.run(["npm", "install"], check=True)

print("Compilazione build di produzione (Vite)...")
subprocess.run(["npm", "run", "build"], check=True)

print("Verifica server e tsx...")
if not os.path.exists("node_modules/tsx"):
    subprocess.run(["npm", "install", "tsx"], check=True)

print("Riavvio PM2 (mantenendo porte e configurazioni originali)...")
try:
    subprocess.run(["pm2", "restart", "maestro-studio", "--update-env"], check=True)
except Exception as e:
    print("Avvio PM2 iniziale:", e)
    subprocess.run(["pm2", "start", "server.ts", "--name", "maestro-studio", "--interpreter", "npx", "--interpreter-args", "tsx"], check=True)

print("=== Aggiornamento completato con successo! Tutti i nuovi strumenti sono attivi. ===")
